const base = pm.environment.get("baseUrl");
const adm = { Authorization: "Bearer " + pm.environment.get("adminToken"), "Content-Type": "application/json" };
const done = () => {};
pm.sendRequest({ url: base + "/api/settings", header: adm }, (e, r) => {
  if (!pm.environment.get("settingsBackup")) pm.environment.set("settingsBackup", JSON.stringify(r.json()));
  const s = Object.assign({}, r.json(), { lockAfterAttempts: 3, lockMinutes: 1 });
  pm.sendRequest({ url: base + "/api/settings", method: "PUT", header: adm,
    body: { mode: "raw", raw: JSON.stringify(s) } }, () => { 
    const u = "lock_astra_" + Date.now();
    pm.environment.set("lockUsername", u);
    const wrong = (n, cb) => pm.sendRequest({ url: base + "/api/auth/login", method: "POST",
      header: { "Content-Type": "application/json" },
      body: { mode: "raw", raw: JSON.stringify({ username: u, password: "wrong_pass" }) } }, (e, r) => {
        pm.test("неверная попытка " + n + " → 401, осталось " + (3 - n), () => {
          pm.expect(r.code).to.eql(401);
          pm.expect(r.json().detail).to.include((3 - n) + " attempt(s) left");
        });
        cb();
      });
    pm.sendRequest({ url: base + "/api/users", method: "POST", header: adm,
      body: { mode: "raw", raw: JSON.stringify({ username: u, password: "pass123", firstName: "Lock", lastName: "Astra",
        email: u + "@test.local", userType: "LEARNER" }) } }, (e, r) => {
        if (r.code === 201) pm.environment.set("lockUserId", r.json().id);
        wrong(1, () => wrong(2, done));
      }); });
});

