function poll(url, token, found, done, tries = 20) {
  pm.sendRequest({ url, method: "GET", header: { Authorization: "Bearer " + token } }, (err, res) => {
    const ok = !err && res.code === 200 && found(res.json());
    if (ok || tries <= 1) return done(ok, res);
    setTimeout(() => poll(url, token, found, done, tries - 1), 500);
  });
}
